// Gzip size budget of every client asset index.html can reference (TODO_V5 PROC-03.b): the list is read
// from Inject/TransformationPatches.cs, each file of Web/ is gzipped, and jux-i18n.js, generated by the
// server from the client.* keys of the language files, is rebuilt here as the server serves it (A-15.a).
// Fails when an asset exceeds its budget by more than 2 %, has no budget, or a budget names no asset; a
// budget only rises with a "Budget: <reason>" commit trailer (ci/static-checks.mjs).
//   node ci/asset-budget.mjs           check against ci/asset-budget.json
//   node ci/asset-budget.mjs --print   print the measured sizes as the JSON "assets" table

import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { gzipSync } from 'node:zlib';

const PLUGIN_DIR = 'src/Jellyfin.Plugin.JuxHomepage';
const BUDGET_FILE = 'ci/asset-budget.json';
const I18N_ASSET = 'jux-i18n.js';
const TOLERANCE = 0.02;

/**
 * The client assets declared in TransformationPatches.ClientAssets, in declaration order.
 * @param {string} source The C# source of TransformationPatches.
 * @returns {string[]}
 */
export function injectedAssets(source) {
    const list = /ClientAsset\[\] ClientAssets =\s*\[([\s\S]*?)\];/.exec(source)?.[1] ?? '';
    return [...list.matchAll(/new\(\s*(?:"([\w.-]+)"|(ClientI18nAsset))\s*,/g)].map((m) => m[1] ?? I18N_ASSET);
}

/**
 * Compares measured gzip sizes with their budgets.
 * @param {Record<string, number>} measured
 * @param {Record<string, number>} budget
 * @returns {{errors: string[], warnings: string[]}}
 */
export function compareAssets(measured, budget) {
    const errors = [];
    const warnings = [];
    for (const [asset, size] of Object.entries(measured)) {
        const limit = budget[asset];
        if (typeof limit !== 'number') {
            errors.push(`${asset} (${size} B gzip) has no budget in ${BUDGET_FILE}.`);
        } else if (size > limit * (1 + TOLERANCE)) {
            errors.push(`${asset} is ${size} B gzip, over its budget of ${limit} B + ${TOLERANCE * 100} %.`);
        } else if (size < limit * (1 - TOLERANCE)) {
            warnings.push(`${asset} is ${size} B gzip, under its budget of ${limit} B: lower the budget.`);
        }
    }
    for (const asset of Object.keys(budget).filter((a) => !(a in measured))) {
        errors.push(`${BUDGET_FILE} budgets ${asset}, which index.html no longer references.`);
    }
    return { errors, warnings };
}

/**
 * jux-i18n.js as LocalizationService.GetClientScript builds it: the client.* keys of each language,
 * serialized with System.Text.Json's default encoder (non-ASCII and HTML-sensitive characters as
 * uppercase \uXXXX). Byte-identical to the script 8096 served for v2.16.0 (A-15.a).
 * @param {[string, string][]} languages Language files as [file name, JSON text], sorted by name.
 * @returns {string}
 */
export function clientI18nScript(languages) {
    const dictionaries = Object.fromEntries(languages.map(([file, text]) => [
        file.replace(/\.json$/, ''),
        Object.fromEntries(Object.entries(JSON.parse(text)).filter(([key]) => key.startsWith('client.')))
    ]));
    const unicode = (c) => `\\u${c.charCodeAt(0).toString(16).toUpperCase().padStart(4, '0')}`;
    const body = JSON.stringify(dictionaries).replace(/[^\x20-\x7e]|['<>&+`]/g, unicode).replace(/\\"/g, '\\u0022');
    return `window.JuxI18n = ${body};\n`;
}

// Line endings normalized to LF, as committed: a Windows checkout (core.autocrlf) measures what the CI does.
function gzipSize(buffer) {
    return gzipSync(Buffer.from(buffer.toString('utf8').replace(/\r\n/g, '\n'), 'utf8')).length;
}

function measure() {
    const source = readFileSync(join(PLUGIN_DIR, 'Inject/TransformationPatches.cs'), 'utf8');
    const languages = readdirSync(join(PLUGIN_DIR, 'Localization'))
        .filter((f) => f.endsWith('.json'))
        .sort()
        .map((f) => [f, readFileSync(join(PLUGIN_DIR, 'Localization', f), 'utf8')]);
    return Object.fromEntries(injectedAssets(source).map((asset) => [
        asset,
        asset === I18N_ASSET ? gzipSize(Buffer.from(clientI18nScript(languages))) : gzipSize(readFileSync(join(PLUGIN_DIR, 'Web', asset)))
    ]));
}

function main() {
    const measured = measure();
    if (process.argv.includes('--print')) {
        console.log(JSON.stringify(measured, null, 4));
        return;
    }
    const { errors, warnings } = compareAssets(measured, JSON.parse(readFileSync(BUDGET_FILE, 'utf8')).assets);
    warnings.forEach((w) => console.log(`warning: ${w}`));
    errors.forEach((e) => console.error(`error: ${e}`));
    const total = Object.values(measured).reduce((a, b) => a + b, 0);
    console.log(`Asset budget: ${Object.keys(measured).length} assets, ${total} B gzip, ${errors.length} error(s), ${warnings.length} warning(s).`);
    process.exitCode = errors.length > 0 ? 1 : 0;
}

if (process.argv[1]?.endsWith('asset-budget.mjs')) {
    main();
}
